import type { Element, ElementContent, Root as HastRoot } from 'hast';
import { readFile } from 'node:fs/promises';
import { join } from 'node:path';
import { SKIP, visit } from 'unist-util-visit';

// Game media (ADR-0007): icons, item cards and maps, generated by scripts/media/build.mjs into
// content/media/*.json, with the image files under public/img/. The core only reads the JSON
// and emits plain HTML pointing at those files; the site styles it.

export interface ItemCard {
  id: string;
  url: string;
  icon?: string;
  grade: string;
  category: string;
  tradable: boolean;
  drops: { npc: string; id: string; min: number; max: number; chance: number; places: string[]; spawns: Record<string, number> }[];
  gathers: { node: string; id: string; places: string[] }[];
  dungeons: string[];
  shops: { shop: string; faction?: string; vendor?: string; price?: string }[];
  recipes: { profession: string; mastery: number; faction?: string; makes: number; inputs: { name: string; qty: number }[] }[];
  usedIn: string[];
}

export interface MapImage {
  name: string;
  slug: string;
  img: string;
  width: number;
  height: number;
  url: string;
  subzones: { name: string; kind?: string; x: number; y: number }[];
}

export interface Overlay {
  map: string;
  mapName: string;
  title: string;
  img: string;
  width: number;
  height: number;
  points: [number, number][];
  areas: { label: string; x: number; y: number; r: number; count: number; zone?: string }[];
  route: [number, number][];
  /** Named markers (field bosses, merchants), when the overlay is a marker map. */
  labels?: { x: number; y: number; text: string }[];
}

export interface Media {
  icons: {
    items: Record<string, string>;
    skills: Record<string, Record<string, string>>;
    nodes: Record<string, string>;
    npcs: Record<string, string>;
    classes: Record<string, string>;
  };
  items: Record<string, ItemCard>;
  maps: Record<string, MapImage>;
  overlays: Record<string, Overlay>;
  /** Source ids that item cards and maps cite. */
  meta: { itemSource: string; mapSource: string };
}

export const emptyMedia = (): Media => ({
  icons: { items: {}, skills: {}, nodes: {}, npcs: {}, classes: {} },
  items: {},
  maps: {},
  overlays: {},
  meta: { itemSource: '', mapSource: '' },
});

/** Read content/media/*.json; a missing folder means no media (tests and the demo content). */
export async function loadMedia(contentDir: string): Promise<Media> {
  const media = emptyMedia();
  const read = async (name: string) => {
    try {
      return JSON.parse(await readFile(join(contentDir, 'media', `${name}.json`), 'utf8'));
    } catch {
      return undefined;
    }
  };
  media.icons = { ...media.icons, ...((await read('icons')) ?? {}) };
  media.items = (await read('items')) ?? {};
  media.maps = (await read('maps')) ?? {};
  media.overlays = (await read('overlays')) ?? {};
  media.meta = { ...media.meta, ...((await read('meta')) ?? {}) };
  return media;
}

export interface MediaContext {
  media: Media;
  assetBase: string;
  /** Class whose skill icons win for this section (`classes/<class>/…`). */
  className?: string;
  /** Site path (already base-prefixed) of the guide page for a name, if one exists. */
  pageFor?: (name: string) => string | undefined;
  /** This section's own path, so a page does not link to itself. */
  selfPath?: string;
}

function link(ctx: MediaContext, name: string, children: ElementContent[]): ElementContent[] {
  const href = ctx.pageFor?.(name);
  if (!href || href === ctx.selfPath) return children;
  return [el('a', { href, className: ['gi-link'], dataBased: '' }, children)];
}

type Props = Record<string, string | number | boolean | string[] | undefined>;
const el = (tagName: string, properties: Props, children: ElementContent[] = []): Element => ({
  type: 'element',
  tagName,
  properties: properties as Element['properties'],
  children,
});
const txt = (value: string): ElementContent => ({ type: 'text', value });

/** Icon key for a name: the section's class skills first, then items, other skills, nodes, monsters. */
export function iconFor(ctx: MediaContext, name: string): string | undefined {
  const i = ctx.media.icons;
  const n = name.trim();
  if (ctx.className && i.skills[ctx.className]?.[n]) return i.skills[ctx.className][n];
  if (i.items[n]) return i.items[n];
  for (const c of Object.values(i.skills)) if (c[n]) return c[n];
  return i.nodes[n] ?? i.npcs[n] ?? i.classes[n];
}

export function iconEl(ctx: MediaContext, key: string, size: 'sm' | 'lg' = 'sm'): Element {
  const px = size === 'lg' ? 48 : 24;
  return el('img', {
    className: ['gi', `gi--${size}`],
    src: `${ctx.assetBase}img/icons/${key}.webp`,
    alt: '',
    width: px,
    height: px,
    loading: 'lazy',
    decoding: 'async',
  });
}

/** `:item[Name]`: an icon followed by the name. */
export function inlineItem(ctx: MediaContext, name: string): Element | undefined {
  const key = iconFor(ctx, name);
  if (!key) return undefined;
  return el('span', { className: ['gi-name'] }, link(ctx, name, [iconEl(ctx, key), txt(name)]));
}

const fmtChance = (c: number) => (c >= 10 ? c.toFixed(0) : c >= 1 ? c.toFixed(1) : c.toFixed(2)).replace(/\.0+$/, '') + '%';

/** The short "how to get it" lines on an item card. */
export function howToGet(card: ItemCard): string[] {
  const lines: string[] = [];
  const farm = card.drops.filter((d) => Object.values(d.spawns).reduce((a, b) => a + b, 0) >= 5).slice(0, 2);
  for (const d of farm)
    lines.push(`Drops from ${d.npc} (level ${d.min === d.max ? d.min : `${d.min}–${d.max}`}) in ${d.places[0] ?? 'the open world'}: ${fmtChance(d.chance)} per kill`);
  if (card.gathers.length) lines.push(`Gathered from ${[...new Set(card.gathers.map((g) => g.node))].join(', ')} nodes`);
  if (card.dungeons.length)
    lines.push(`From ${card.dungeons.slice(0, 3).join(', ')}${card.dungeons.length > 3 ? ` and ${card.dungeons.length - 3} more` : ''}`);
  for (const s of card.shops.slice(0, 2)) lines.push(`Sold by ${s.vendor ?? s.shop}${s.faction ? ` (${s.faction})` : ''}${s.price ? `: ${s.price}` : ''}`);
  for (const r of card.recipes.slice(0, 1))
    lines.push(`Crafted with ${r.profession} ${r.mastery}: ${r.inputs.map((g) => `${g.name} ×${g.qty}`).join(', ')}`);
  return lines.length ? lines : ['No source listed in the game data'];
}

/** `::items{names="A; B"}`: a grid of item cards. */
export function itemCards(ctx: MediaContext, names: string[], cite: () => ElementContent): { node: Element; missing: string[] } {
  const missing: string[] = [];
  const cards: ElementContent[] = [];
  for (const name of names) {
    const card = ctx.media.items[name];
    const key = iconFor(ctx, name);
    if (!card && !key) {
      missing.push(name);
      continue;
    }
    const head: ElementContent[] = [];
    if (key) head.push(iconEl(ctx, key, 'lg'));
    const title: ElementContent[] = [
      ctx.pageFor?.(name) && ctx.pageFor(name) !== ctx.selfPath
        ? el('a', { href: ctx.pageFor(name)!, className: ['item-card__name'], dataBased: '' }, [txt(name)])
        : card
          ? el('a', { href: card.url, className: ['item-card__name'] }, [txt(name)])
          : el('span', { className: ['item-card__name'] }, [txt(name)]),
    ];
    if (card) title.push(el('span', { className: ['item-card__grade', `grade--${card.grade.toLowerCase()}`] }, [txt(card.grade)]));
    head.push(el('div', { className: ['item-card__title'] }, title));
    const body: ElementContent[] = [el('div', { className: ['item-card__head'] }, head)];
    if (card) body.push(el('ul', { className: ['item-card__how'] }, howToGet(card).map((l) => el('li', {}, [txt(l)]))));
    cards.push(el('article', { className: ['item-card'] }, body));
  }
  const node = el('div', { className: ['item-cards'], dataItemCards: '' }, [...cards, el('p', { className: ['item-cards__cite'] }, [txt('Game data '), cite()])]);
  return { node, missing };
}

/** One short line on where a gear piece comes from, from its item card. */
export function gearSource(ctx: MediaContext, name: string): string | undefined {
  const c = ctx.media.items[name];
  if (!c) return undefined;
  const live = c.dungeons.filter((d) => !/Ludra/.test(d));
  if (live.length) return `From ${live.slice(0, 2).join(' or ')}`;
  const craft = c.recipes.find((r) => r.profession);
  if (craft) return `Crafted: ${craft.profession} ${craft.mastery}`;
  if (c.recipes.length) return 'Substance Morph';
  const d = c.drops[0];
  if (d) return `Drops from ${d.npc}`;
  if (c.shops.length) return `Sold by ${c.shops[0].vendor ?? c.shops[0].shop}`;
  return undefined;
}

const LEFT = ['Helm', 'Pauldrons', 'Breastplate', 'Gloves', 'Greaves', 'Boots', 'Cloak'];
const RIGHT = ['Weapon', 'Guard', 'Necklace', 'Earrings', 'Ring', 'Bracelet', 'Belt', 'Amulet', 'Rune'];

/**
 * `::loadout{class="Gladiator" items="Helm=Vakron Helm; Weapon=…"}`: the gear for one stage laid out
 * like the in-game equipment window (armor left, class emblem centre, weapon and accessories right).
 */
export function loadout(ctx: MediaContext, attrs: Record<string, string | null | undefined>, cite: () => ElementContent): { node: Element; missing: string[] } {
  const slots = new Map<string, string>();
  for (const pair of (attrs.items ?? '').split(';')) {
    const [slot, name] = pair.split('=').map((s) => s?.trim());
    if (slot && name) slots.set(slot, name);
  }
  const missing: string[] = [];
  const slotEl = (slot: string) => {
    const name = slots.get(slot);
    const key = name ? iconFor(ctx, name) : undefined;
    if (name && !key) missing.push(name);
    const icon = key ? iconEl(ctx, key, 'lg') : el('span', { className: ['loadout__empty'] });
    const label = name ? link(ctx, name, [txt(name)]) : [txt('–')];
    const where = name ? gearSource(ctx, name) : undefined;
    return el('li', { className: ['loadout__slot', name ? '' : 'loadout__slot--empty'].filter(Boolean) }, [
      icon,
      el('span', { className: ['loadout__text'] }, [
        el('span', { className: ['loadout__kind'] }, [txt(slot)]),
        el('span', { className: ['loadout__name'] }, label),
        ...(where ? [el('span', { className: ['loadout__where'] }, [txt(where)])] : []),
      ]),
    ]);
  };
  const cls = attrs.class ? ctx.media.icons.classes[attrs.class] : undefined;
  const centre: ElementContent[] = [];
  if (cls)
    centre.push(el('img', { src: `${ctx.assetBase}img/icons/${cls}.webp`, alt: '', width: 96, height: 96, loading: 'lazy', className: ['loadout__class'] }));
  if (attrs.title) centre.push(el('p', { className: ['loadout__title'] }, [txt(attrs.title)]));
  if (attrs.ilvl) centre.push(el('p', { className: ['loadout__ilvl'] }, [txt(`Item level ${attrs.ilvl}`)]));
  const node = el('figure', { className: ['loadout'], dataLoadout: '' }, [
    el('ul', { className: ['loadout__col'] }, LEFT.filter((s) => slots.has(s) || !attrs.compact).map(slotEl)),
    el('div', { className: ['loadout__centre'] }, centre),
    el('ul', { className: ['loadout__col'] }, RIGHT.filter((s) => slots.has(s)).map(slotEl)),
    el('figcaption', {}, [txt('Item names and icons from the game data '), cite()]),
  ]);
  return { node, missing };
}

const BAR_KEYS = ['1', '2', '3', '4', '5', '6', '7', '8', 'Q', 'E', 'LMB', 'RMB'];
const KEY_NAME: Record<string, string> = { LMB: 'Left mouse', RMB: 'Right mouse' };

/**
 * `::skillbar{title="…" keys="5=A,B,C/macro; E=D/hand; RMB=Macro" note="…" cite="@src"}`: the quick-slot
 * bar. Each key lists its skills in priority order (the bottom row, tried first, comes first) and how it
 * is pressed: `macro` (the macro presses it), `hand` (you press it) or `macro-key` (the macro itself).
 */
export function skillbar(ctx: MediaContext, attrs: Record<string, string | null | undefined>, cite?: ElementContent): { node: Element; missing: string[] } {
  const keys = new Map<string, { skills: string[]; mode: string }>();
  for (const part of (attrs.keys ?? '').split(';')) {
    const m = /^\s*([^=]+?)\s*=\s*(.*?)\s*(?:\/\s*(macro|hand))?\s*$/.exec(part);
    if (!m) continue;
    const skills = m[2].split(',').map((s) => s.trim()).filter(Boolean);
    keys.set(m[1].toUpperCase(), { skills, mode: skills[0] === 'Macro' ? 'macro-key' : (m[3] ?? 'hand') });
  }
  const missing: string[] = [];
  const cols: ElementContent[] = [];
  const list: ElementContent[] = [];
  for (const k of BAR_KEYS) {
    const e = keys.get(k);
    const label = KEY_NAME[k] ?? k;
    const stack: ElementContent[] = [];
    if (e && e.mode !== 'macro-key')
      // Shown top to bottom like the game: the last-priority skill on top, the first-tried at the bottom.
      for (const s of [...e.skills].reverse()) {
        const key = iconFor(ctx, s);
        if (!key) missing.push(s);
        stack.push(
          key
            ? el('img', { src: `${ctx.assetBase}img/icons/${key}.webp`, alt: s, title: s, width: 40, height: 40, loading: 'lazy', className: ['sb-icon'] })
            : el('span', { className: ['sb-icon', 'sb-icon--text'], title: s }, [txt(s)]),
        );
      }
    if (e?.mode === 'macro-key') stack.push(el('span', { className: ['sb-icon', 'sb-icon--macro'], title: 'Macro' }, [txt('Macro')]));
    cols.push(
      el('div', { className: ['sb-key', `sb-key--${e ? e.mode : 'empty'}`] }, [
        el('div', { className: ['sb-stack'] }, stack),
        el('span', { className: ['sb-label'] }, [txt(k === 'LMB' ? 'LMB' : k === 'RMB' ? 'RMB' : k)]),
      ]),
    );
    if (e) {
      const how = e.mode === 'macro-key' ? 'hold it: this is your macro key' : e.mode === 'macro' ? 'pressed by the macro' : 'press it yourself';
      const order: ElementContent[] = [];
      if (e.mode !== 'macro-key') {
        order.push(txt(e.skills.length > 1 ? ': tries ' : ': '));
        e.skills.forEach((s, i) => {
          if (i) order.push(txt(', then '));
          order.push(el('strong', {}, [txt(s)]));
        });
      }
      list.push(el('li', {}, [el('span', { className: ['sb-li-key'] }, [txt(label)]), txt(` (${how})`), ...order]));
    }
  }
  const legend = el('p', { className: ['sb-legend'] }, [
    el('span', { className: ['sb-dot', 'sb-dot--macro'] }), txt('pressed by the macro '),
    el('span', { className: ['sb-dot', 'sb-dot--hand'] }), txt('press it yourself '),
    el('span', { className: ['sb-dot', 'sb-dot--macro-key'] }), txt('macro key. Each key tries its bottom skill first.'),
  ]);
  const caption: ElementContent[] = [];
  if (attrs.title) caption.push(el('strong', {}, [txt(attrs.title)]), txt('. '));
  if (attrs.note) caption.push(txt(attrs.note + ' '));
  if (cite) caption.push(cite);
  const node = el('figure', { className: ['skillbar'], dataSkillbar: '' }, [
    el('div', { className: ['sb-bar'] }, cols),
    legend,
    el('ol', { className: ['sb-list'] }, list),
    el('figcaption', {}, caption),
  ]);
  return { node, missing };
}

/** `::map{id=…}` (an overlay) or `::map{map=…}` (a whole map with area names). */
export function mapFigure(ctx: MediaContext, attrs: Record<string, string | null | undefined>, cite: () => ElementContent): Element | undefined {
  const ov = attrs.id ? ctx.media.overlays[attrs.id] : undefined;
  const whole = attrs.map ? Object.values(ctx.media.maps).find((m) => m.slug === attrs.map) : undefined;
  if (!ov && !whole) return undefined;
  const w = ov?.width ?? whole!.width;
  const h = ov?.height ?? whole!.height;
  const svg: ElementContent[] = [];
  if (ov) {
    const scale = Math.max(w, h) / 600;
    for (const a of ov.areas)
      svg.push(el('circle', { cx: a.x, cy: a.y, r: a.r, className: ['gmap__area', a.label === 'Best spot' ? 'gmap__area--best' : 'gmap__area--alt'] }));
    if (ov.route.length > 1)
      svg.push(el('polyline', { points: ov.route.map((p) => p.join(',')).join(' '), className: ['gmap__route'], style: `stroke-width:${(3 * scale).toFixed(1)}` }));
    for (const [x, y] of ov.points) svg.push(el('circle', { cx: x, cy: y, r: (4 * scale).toFixed(1), className: ['gmap__pt'] }));
    ov.route.slice(0, -1).forEach(([x, y], i) => {
      if (ov.route.length <= 2 && i > 0) return;
      svg.push(el('circle', { cx: x, cy: y, r: (9 * scale).toFixed(1), className: ['gmap__stop'] }));
      svg.push(el('text', { x, y, dy: '0.35em', className: ['gmap__stop-n'], style: `font-size:${(11 * scale).toFixed(1)}px` }, [txt(String(i + 1))]));
    });
    for (const l of ov.labels ?? []) {
      svg.push(el('circle', { cx: l.x, cy: l.y, r: (6 * scale).toFixed(1), className: ['gmap__stop'] }));
      svg.push(el('text', { x: l.x, y: l.y - 10 * scale, className: ['gmap__label'], style: `font-size:${(12 * scale).toFixed(1)}px` }, [txt(l.text)]));
    }
    for (const a of ov.areas)
      svg.push(el('text', { x: Math.min(Math.max(a.x, (a.zone ?? '').length * 4.5 * scale + 30 * scale), w - (a.zone ?? '').length * 4.5 * scale - 30 * scale), y: Math.max(14 * scale, a.y - a.r - 6 * scale), className: ['gmap__label'], style: `font-size:${(14 * scale).toFixed(1)}px` }, [txt(a.label === 'Best spot' ? `Best: ${a.zone ?? ''}` : `Alt: ${a.zone ?? ''}`)]));
  } else {
    const scale = w / 600;
    // Main areas only: villages and battlefield sub-areas would crowd the labels.
    // Skip a label that would overlap one already placed (rough text box from the font size).
    const fs = 9 * scale;
    const placed: { x: number; y: number; w: number }[] = [];
    for (const z of whole!.subzones.filter((z) => z.kind !== 'village' && z.kind !== 'battlefield')) {
      const wz = z.name.length * fs * 0.55;
      if (placed.some((p) => Math.abs(p.y - z.y) < fs * 1.3 && Math.abs(p.x - z.x) < (p.w + wz) / 2 + fs * 0.3)) continue;
      placed.push({ x: z.x, y: z.y, w: wz });
      const x = Math.min(Math.max(z.x, wz / 2 + 4), w - wz / 2 - 4);
      svg.push(el('text', { x, y: Math.min(Math.max(z.y, fs), h - 4), className: ['gmap__zone'], style: `font-size:${fs.toFixed(1)}px` }, [txt(z.name)]));
    }
  }
  const img = el('img', { src: `${ctx.assetBase}${ov?.img ?? whole!.img}`, alt: ov ? `${ov.title} on the ${ov.mapName} map` : `${whole!.name} map`, width: w, height: h, loading: 'lazy', decoding: 'async' });
  const frame = el('div', { className: ['gmap__frame'] }, [img, el('svg', { viewBox: `0 0 ${w} ${h}`, className: ['gmap__svg'], ariaHidden: 'true' }, svg)]);
  const caption: ElementContent[] = [];
  if (ov?.labels?.length) caption.push(el('strong', {}, [txt(ov.title)]), txt(` on ${ov.mapName}. `));
  else if (ov) {
    caption.push(el('strong', {}, [txt(ov.title)]), txt(` on ${ov.mapName}. `));
    caption.push(txt(`Dots: ${ov.points.length} positions. Circles: ${ov.areas.map((a) => `${a.label.toLowerCase()} (${a.zone ?? 'unnamed area'}, ${a.count})`).join('; ')}. `));
    if (ov.route.length > 2) caption.push(txt('Numbered line: a suggested loop through the best spot, worked out from the positions. '));
  } else caption.push(el('strong', {}, [txt(whole!.name)]), txt(' with its area names. '));
  caption.push(txt('Map and positions from the game data '), cite());
  return el('figure', { className: ['gmap'], dataMap: attrs.id ?? attrs.map ?? '' }, [frame, el('figcaption', {}, caption)]);
}

/**
 * Put icons in front of known names without any markup: bold text, table cells and list
 * items that are exactly a name (optionally followed by "×N" or a level).
 */
export function autoIcons(tree: HastRoot, ctx: MediaContext) {
  const NAME_TAIL = /^(.+?)(\s*(?:×|x)\s*\d[\d,]*|\s+\d+(?:\s*\+\s*\d+\s*bonus)?|\s*\(level [^)]*\))?$/;
  const lead = (node: Element): { text: ElementContent & { type: 'text' }; name: string; key: string } | undefined => {
    const first = node.children[0];
    if (!first || first.type !== 'text') return undefined;
    const value = first.value;
    const m = NAME_TAIL.exec(value.trim());
    const name = m?.[1]?.trim();
    if (!name) return undefined;
    const key = iconFor(ctx, name);
    return key ? { text: first, name, key } : undefined;
  };
  visit(tree, 'element', (node: Element, index, parent) => {
    if (node.tagName === 'a') {
      // Site-absolute links in Markdown ("/world/materials/raw-leather") get the base path.
      // Links we generated (data-based) already carry the base path.
      const href = String(node.properties?.href ?? '');
      if (node.properties?.dataBased !== undefined) delete node.properties.dataBased;
      else if (href.startsWith('/') && !href.startsWith('//')) node.properties = { ...node.properties, href: ctx.assetBase + href.slice(1) };
      // Names inside an existing link keep that link (the subtree is skipped).
      return SKIP;
    }
    if (node.properties?.className && String(node.properties.className).includes('gi')) return SKIP;
    if (node.tagName === 'figure' || node.tagName === 'pre' || node.tagName === 'code') return SKIP;
    if (node.tagName === 'strong') {
      const l = lead(node);
      if (l && l.text.value.trim() === l.name && parent && index !== undefined) {
        node.children = link(ctx, l.name, [iconEl(ctx, l.key), ...node.children]);
        node.properties = { ...node.properties, className: ['gi-name'] };
      }
      return SKIP;
    }
    if (/^h[2-4]$/.test(node.tagName)) {
      // "Orichalcum Ingot (mastery 1)", "Shadowstrike": an icon before the heading text.
      const first = node.children[0];
      if (first?.type === 'text') {
        const name = first.value.replace(/\s*\([^)]*\)\s*$/, '').trim();
        const key = iconFor(ctx, name);
        if (key && name === first.value.replace(/\s*\([^)]*\)\s*$/, '').trim() && node.children.length === 1) node.children.unshift(iconEl(ctx, key));
      }
      return SKIP;
    }
    if (node.tagName === 'td' || node.tagName === 'li') {
      // A list item / cell that starts with a bold name is handled by the strong rule.
      const l = lead(node);
      if (l) {
        // "Raw Leather ×20": icon, then the name linked to its page, then the rest as text.
        const rest = l.text.value.slice(l.text.value.indexOf(l.name) + l.name.length);
        const before = l.text.value.slice(0, l.text.value.indexOf(l.name));
        node.children.splice(0, 1, ...(before ? [txt(before)] : []), ...link(ctx, l.name, [iconEl(ctx, l.key), txt(l.name)]), ...(rest ? [txt(rest)] : []));
        return;
      }
      // "A → B, C" (macro slots, combos) and "A ×2, B ×7" (recipe inputs): an icon before each
      // name when every part is a name (a part may end in "×N" or a note in brackets).
      const first = node.children[0];
      if (first?.type !== 'text' || !/→|, /.test(first.value)) return;
      const parts = first.value.split(/(\s*→\s*|,\s*)/);
      const PART = /^(.+?)((?:\s*×\s*\d[\d,]*)?(?:\s*\([^)]*\))?)$/;
      const split = parts.map((p, i) => (i % 2 ? null : PART.exec(p.trim())));
      if (!split.every((m, i) => i % 2 || (m && iconFor(ctx, m[1].trim())))) return;
      const out: ElementContent[] = [];
      parts.forEach((p, i) => {
        if (i % 2) return out.push(txt(p));
        const [, name, tail] = split[i]!;
        out.push(...link(ctx, name.trim(), [iconEl(ctx, iconFor(ctx, name.trim())!), txt(name.trim())]));
        if (tail) out.push(txt(tail));
      });
      node.children.splice(0, 1, ...out);
    }
  });
}
